'use strict';
// Club-channel feed of confirmed career transfers. No network publishing or simulated deals.
const ClubNews60A={channel:'all',page:0,size:12,
 matchesType(p){return !this.type60b||this.type60b==='all'||this.type60b===(p.kind?'results':'transfers');},
 matchesChannel(p,c){return c==='all'||c==='mine'&&(p.to.id===S.club||p.from?.id===S.club)||Number.isInteger(c)&&p.to.id===c;},
 valeChannel(){return '';},
 palette(t){const brands={'Team Yandex':['#ee302c','#ffffff'],'Xtreme Gaming':['#d8ddd1','#131810'],'PARIVISION':['#00b9a5','#101a17'],'Team Spirit':['#e9e9e4','#10120f'],'BetBoom Team':['#ed2944','#ffffff'],'OG':['#63b86a','#ffffff'],'Team Liquid':['#b8ccdd','#101d30'],'Aurora Gaming':['#14b8c8','#071c25'],'Natus Vincere':['#f4d52b','#15140d'],'1w Team':['#68d128','#11180b'],'GamerLegion':['#d23632','#ffffff']};return brands[t.name]||['#bfc6b5','#141a10'];},
 club(t){return t?{id:t.id,name:t.name,short:t.short||t.name,logo5:t.logo5||null,fiction:!!t.fiction}:null;},
 make(e,seq,from){const p=S.players[e.player],to=S.teams[e.to];if(!p||!to||!Number.isFinite(e.fee)||e.fee<0||!Number.isInteger(e.day)||e.day<0||e.day>S.day||!Number.isInteger(e.role)||e.role<0||e.role>4)return null;const bio=TransferReveal52.identity({...p,name:e.name});return {id:seq,day:e.day,player:e.player,nick:e.name,role:e.role,first:bio?.first||'',last:bio?.last||'',photo:photo20({...p,name:e.name})||null,from:this.club(S.teams[from]),to:this.club(to),fee:e.fee,palette:this.palette(to)};},
 items(){const history=S.transfersV1||[],snapshots=new Map((S.clubNews60a?.posts||[]).map(p=>[p.id,p])),released=new Map(),posts=[];for(let i=history.length-1;i>=0;i--){const e=history[i],seq=history.length-i;if(e.type==='release'){released.set(e.player,e);continue;}if(e.type!=='sign'||!Number.isInteger(e.to))continue;const old=released.get(e.player),from=Number.isInteger(e.from)?e.from:old&&old.day===e.day&&old.fee===e.fee&&old.window===e.window?old.from:null;released.delete(e.player);const post=snapshots.get(seq)||this.make(e,seq,from);if(post)posts.push(post);}return posts.reverse();},
 capture(){const e=S.transfersV1?.[0];if(e?.type!=='sign')return;const id=S.transfersV1.length,store=S.clubNews60a??={version:1,posts:[]};if(store.posts.some(p=>p.id===id))return;const old=S.transfersV1.slice(1).find(r=>r.player===e.player),from=Number.isInteger(e.from)?e.from:old?.type==='release'&&old.day===e.day&&old.fee===e.fee&&old.window===e.window?old.from:null,post=this.make(e,id,from);if(post)store.posts.push(post);},
 choose(channel){if(channel==='all'||channel==='mine'||channel==='vale'||Number.isInteger(channel)&&S.teams[channel]){this.channel=channel;this.page=0;render();}},
 next(step){this.page=Math.max(0,this.page+step);render();},
 verified(label='Официальный канал клуба'){return '<span class="cn-verified" title="'+esc(label)+' в игровой карьере" aria-label="'+esc(label)+'">✓</span>';},
 openClub(id){if(!S.teams[id])return;playerClub20=String(id);playerSearch20='';playerRole20='';go('players');},
 post(p){const color=/^#[0-9a-f]{6}$/i.test(p.palette?.[0])?p.palette[0]:'#bfc6b5',ink=/^#[0-9a-f]{6}$/i.test(p.palette?.[1])?p.palette[1]:'#141a10';return '<article class="cn-post" data-post="'+p.id+'"><header>'+clubAvatar12(p.to,true)+'<div><strong>'+esc(p.to.name)+'</strong>'+this.verified()+'<small>@'+esc((p.to.short||'club').toLowerCase().replace(/[^a-z0-9]/g,''))+' · '+esc(date(p.day))+'</small></div></header><p class="cn-caption">Добро пожаловать, '+esc(p.nick)+'! '+esc([p.first,p.last].filter(Boolean).join(' ')||p.nick)+' присоединяется к нашей команде.'+'</p><div class="cn-poster" style="--club-color:'+color+';--club-ink:'+ink+'"><div class="cn-poster-brand">'+clubAvatar12(p.to,false)+'<b>'+esc(p.to.name)+'</b></div><div class="cn-copy"><span>WELCOME</span><h2>'+esc(p.nick)+'</h2><p>'+esc([p.first,p.last].filter(Boolean).join(' '))+'</p><b class="cn-role">POS '+String(p.role+1).padStart(2,'0')+' / '+esc(ROLES[p.role])+'</b><div class="cn-price"><small>'+(p.from?'СУММА ТРАНСФЕРА':'ПОДПИСНОЙ БОНУС')+'</small><strong>'+esc(cash(p.fee))+'</strong></div></div><div class="cn-player">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="'+esc(p.nick)+'" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false">':'')+'<div class="cn-no-photo" '+(p.photo?'hidden':'')+'><b>'+esc(p.nick.slice(0,2))+'</b><small>Фото недоступно</small></div></div><span class="cn-signed">SIGNED</span><div class="cn-route">'+(p.from?clubAvatar12(p.from,true):'<span class="cn-fa">FA</span>')+'<b>'+esc(p.from?.name||'Свободный агент')+'</b><span>→</span>'+clubAvatar12(p.to,true)+'<b>'+esc(p.to.name)+'</b></div></div><footer><span>✓ Переход подтверждён</span>'+btn('Профиль игрока →','profile('+p.player+')')+btn('Состав '+p.to.name+' →','ClubNews60A.openClub('+p.to.id+')')+'</footer></article>';},
 view(){const all=this.items(),channel=this.channel,filtered=all.filter(p=>this.matchesType(p)&&this.matchesChannel(p,channel)),page=Math.min(this.page,Math.max(0,Math.ceil(filtered.length/this.size)-1)),posts=filtered.slice(page*this.size,(page+1)*this.size),teams=[...S.teams].sort((a,b)=>Number(all.some(p=>p.to.id===b.id))-Number(all.some(p=>p.to.id===a.id))||a.name.localeCompare(b.name));return '<div class="cn-layout"><aside class="cn-channels"><h2>Каналы</h2><nav aria-label="Каналы новостей"><button aria-pressed="'+(channel==='all')+'" onclick="ClubNews60A.choose(\'all\')">Все новости <b>'+all.length+'</b></button><button aria-pressed="'+(channel==='mine')+'" onclick="ClubNews60A.choose(\'mine\')">Мой клуб</button>'+this.valeChannel()+teams.map(t=>'<button aria-pressed="'+(channel===t.id)+'" onclick="ClubNews60A.choose('+t.id+')">'+clubAvatar12(t,true)+'<span>'+esc(t.name)+'</span>'+this.verified()+'</button>').join('')+'</nav></aside><section class="cn-feed" aria-label="Лента клубов">'+(this.typeFilters?.()||'')+'<div class="cn-feed-heading"><h2>'+esc(channel==='all'?'Все новости':channel==='mine'?'Мой клуб':channel==='vale'?'Alex Vale':S.teams[channel]?.name||'Канал')+'</h2><small>'+filtered.length+' ПУБЛИКАЦИЙ</small></div>'+(posts.length?posts.map(p=>this.post(p)).join(''):'<div class="panel cn-empty"><h2>Новая глава ещё не объявлена</h2><p>Здесь появятся подтверждённые трансферы и результаты этой карьеры. Публикации создаются автоматически.</p>'+btn('Открыть трансферы',"go('market')",true)+'</div>')+'<div class="cn-pagination">'+btn('← Назад','ClubNews60A.next(-1)',false,page===0)+'<span>'+(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/this.size))+'</span>'+btn('Далее →','ClubNews60A.next(1)',false,(page+1)*this.size>=filtered.length)+'</div></section><aside class="cn-latest"><h2>В ленте</h2>'+all.slice(0,5).map(p=>'<button onclick="ClubNews60A.choose('+(p.author?"'vale'":p.to.id)+')">'+(p.author?Vale8.avatar():clubAvatar12(p.to,true))+'<div><b>'+esc(p.author?.name||p.to.name)+'</b>'+this.verified(p.author?'Канал Alex Vale':'Официальный канал клуба')+'<p>'+esc(p.kind?p.caption:'Добро пожаловать, '+p.nick+'!')+'</p><small>'+esc(date(p.day))+'</small></div></button>').join('')+'<p class="cn-disclosure">Новости и отметки каналов относятся к событиям вашей игровой карьеры.</p></aside></div>';}
};
PAGES.splice(PAGES.findIndex(p=>p[0]==='market')+1,0,['news60a','▤','Новости']);
const entryBeforeNews60A=transferEntryV1;transferEntryV1=function(...args){const r=entryBeforeNews60A(...args);ClubNews60A.capture();return r;};
const renderBeforeNews60A=render;render=function(...args){const r=renderBeforeNews60A(...args);if(S&&page==='news60a')$('app').innerHTML=ClubNews60A.view();return r;};
const navBeforeNews60A=MatchdayHome.nav;MatchdayHome.nav=function(...args){return navBeforeNews60A.apply(this,args).replace('</nav>','<button type="button" onclick="go(\'news60a\')" '+(page==='news60a'?'aria-current="page"':'')+'>НОВОСТИ</button></nav>');};
const freshBeforeNews60A=fresh,migrateBeforeNews60A=migrate;fresh=function(...args){ClubNews60A.channel='all';ClubNews60A.page=0;return freshBeforeNews60A(...args);};migrate=function(...args){ClubNews60A.channel='all';ClubNews60A.page=0;return migrateBeforeNews60A(...args);};
const validBeforeNews60A=validSave;validSave=function(x){if(!validBeforeNews60A(x))return false;const m=x.clubNews60a;if(!m)return true;if(m.version!==1||!Array.isArray(m.posts))return false;const ids=new Set(),club=c=>c&&Number.isInteger(c.id)&&!!x.teams[c.id]&&typeof c.name==='string'&&typeof c.short==='string'&&(c.logo5===null||typeof c.logo5==='string')&&typeof c.fiction==='boolean';return m.posts.every(p=>{if(!Number.isInteger(p.id)||p.id<1||ids.has(p.id)||p.id>(x.transfersV1?.length||0)||!Number.isInteger(p.day)||p.day<0||p.day>x.day||!Number.isInteger(p.player)||!x.players[p.player]||typeof p.nick!=='string'||!Number.isInteger(p.role)||p.role<0||p.role>4||typeof p.first!=='string'||typeof p.last!=='string'||(p.photo!==null&&typeof p.photo!=='string')||!Number.isFinite(p.fee)||p.fee<0||!club(p.to)||(p.from!==null&&!club(p.from))||!Array.isArray(p.palette)||p.palette.length!==2||p.palette.some(c=>!/^#[0-9a-f]{6}$/i.test(c)))return false;const e=x.transfersV1[x.transfersV1.length-p.id];if(!e||e.type!=='sign'||e.player!==p.player||e.to!==p.to.id||e.fee!==p.fee||e.day!==p.day)return false;ids.add(p.id);return true;});};
const patchBeforeNews60A=patchViewV1;
patchViewV1=function(...args){return '<section class="panel"><span class="eyebrow">V6.0 A / CLUB CHANNELS</span><h1>Новости клубов</h1><p>Лента подтверждённых трансферов вашей карьеры. Каналы клубов, постеры в клубных цветах, реальные суммы, профили игроков и составы команд. Фильтры «Все новости» и «Мой клуб».</p><p>Исторические переходы берутся из журнала сделок. Новые публикации сохраняют имя игрока, названия клубов, фото и сумму на момент перехода. Отметки каналов относятся к игровому миру.</p></section>'+patchBeforeNews60A(...args);};
